describe('Search Filter - Exclude Term with Minus Prefix', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should exclude a term from search results when prefixed with minus sign', () => {
    // Perform initial search to establish baseline
    cy.get('[data-testid="search-input"]').type('javascript tutorial');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').then(($results) => {
      const initialCount = $results.length;
      expect(initialCount).to.be.greaterThan(0);
    });

    // Clear and search with exclusion term
    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-input"]').type('javascript -tutorial');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Verify excluded term does not appear in results
    cy.get('[data-testid="result-item"]').each(($result) => {
      cy.wrap($result).should('not.contain', 'tutorial');
    });

    // Verify results still contain the included term
    cy.get('[data-testid="result-item"]').first().should('contain', 'javascript');
  });

  it('should handle multiple excluded terms in a single search query', () => {
    cy.get('[data-testid="search-input"]').type('web development -php -asp');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Verify multiple excluded terms are not in results
    cy.get('[data-testid="result-item"]').each(($result) => {
      cy.wrap($result).should('not.contain', 'php');
      cy.wrap($result).should('not.contain', 'asp');
    });

    // Verify included terms are present
    cy.get('[data-testid="result-item"]').first().should('contain', 'web');
  });

  it('should display appropriate message when all results are excluded', () => {
    cy.get('[data-testid="search-input"]').type('-javascript -python -java');
    cy.get('[data-testid="search-button"]').click();

    // Should show no results message
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });

  it('should handle edge case of only minus sign without term', () => {
    cy.get('[data-testid="search-input"]').type('javascript -');
    cy.get('[data-testid="search-button"]').click();

    // Should treat trailing minus as part of search or ignore it gracefully
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').first().should('contain', 'javascript');
  });

  it('should preserve excluded terms when modifying search query', () => {
    cy.get('[data-testid="search-input"]').type('python -django');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Modify search by adding another term
    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-input"]').type('python web -django');
    cy.get('[data-testid="search-button"]').click();

    // Verify django is still excluded
    cy.get('[data-testid="result-item"]').each(($result) => {
      cy.wrap($result).should('not.contain', 'django');
    });
  });
});
